CREATE OR REPLACE FUNCTION public.fn_get_material_loan_by_id(p_loan_id uuid)  RETURNS TABLE(id uuid, order_id uuid, order_item_id uuid, material_product_id uuid, organization_id uuid, classroom_id uuid, quantity_issued integer, issued_at timestamp with time zone, due_date timestamp with time zone, actual_return_date timestamp with time zone, return_status character varying, deposit_amount numeric, deposit_status character varying, notes text, created_at timestamp with time zone, updated_at timestamp with time zone, product_name character varying, product_sku character varying, order_number character varying, classroom_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          l.id, l.order_id, l.order_item_id, l.material_product_id, l.organization_id,         l.classroom_id, l.quantity_issued, l.issued_at, l.due_date, l.actual_return_date,         l.return_status, l.deposit_amount, l.deposit_status, l.notes, l.created_at, l.updated_at,         p.name AS product_name, p.sku AS product_sku, o.order_number, c.name AS classroom_name     FROM material_loans l     JOIN material_products p ON l.material_product_id = p.id     JOIN material_orders o ON l.order_id = o.id     LEFT JOIN classrooms c ON l.classroom_id = c.id     WHERE l.id = p_loan_id; $function$ ;
